package cn.kejian.app;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import org.json.*;import java.time.ZoneId;import java.util.*;
public final class AlarmScheduler {
 static final String PREF="kejian_private",STATE="kejian-prototype-v1",CHANNEL="kejian_reminders";
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE);}
 static void channel(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);NotificationChannel ch=new NotificationChannel(CHANNEL,"作业与活动提醒",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("你自己设定的日期与时间提醒");n.createNotificationChannel(ch);}
 static boolean enabled(Context c){channel(c);NotificationManager n=c.getSystemService(NotificationManager.class);NotificationChannel ch=n.getNotificationChannel(CHANNEL);return n.areNotificationsEnabled()&&ch!=null&&ch.getImportance()!=NotificationManager.IMPORTANCE_NONE;}
 static boolean exact(Context c){return Build.VERSION.SDK_INT<31||c.getSystemService(AlarmManager.class).canScheduleExactAlarms();}
 static JSONArray reminders(Context c){try{return new JSONObject(prefs(c).getString(STATE,"{}")).optJSONArray("reminders")==null?new JSONArray():new JSONObject(prefs(c).getString(STATE,"{}")).getJSONArray("reminders");}catch(Exception e){return new JSONArray();}}
 static JSONObject reminder(Context c,String id){JSONArray a=reminders(c);for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(r!=null&&id.equals(r.optString("id")))return r;}return null;}
 static long at(JSONObject r){return AlarmPlan.timestamp(r.optString("date"),r.optString("time"),ZoneId.systemDefault());}
 static PendingIntent intent(Context c,String id){Intent i=new Intent(c,ReminderReceiver.class).setAction("cn.kejian.app.REMIND").setData(Uri.parse("kejian://reminder/"+Uri.encode(id))).putExtra("id",id);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static synchronized void reconcile(Context c){channel(c);AlarmManager a=c.getSystemService(AlarmManager.class);Set<String> old=new HashSet<>(prefs(c).getStringSet("alarm_ids",Collections.emptySet()));JSONArray rows=reminders(c);Set<String> fresh=new HashSet<>(),fired=new HashSet<>(prefs(c).getStringSet("fired_ids",Collections.emptySet()));for(String id:old)a.cancel(intent(c,id));boolean allowed=enabled(c),precise=exact(c);for(int n=0;n<rows.length();n++){JSONObject r=rows.optJSONObject(n);if(r==null)continue;String id=r.optString("id");if(id.isEmpty()||id.length()>256)continue;fresh.add(id);if(fired.contains(id)||!allowed)continue;try{long when=at(r);if(when<=System.currentTimeMillis())continue;PendingIntent pi=intent(c,id);try{if(precise)a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);}catch(SecurityException ex){a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);}}catch(Exception ex){/* Invalid/ambiguous timestamps remain records but are never guessed. */}}
 fired.retainAll(fresh);prefs(c).edit().putStringSet("alarm_ids",fresh).putStringSet("fired_ids",fired).commit();
 }
 static synchronized void deliver(Context c,String id){JSONObject r=reminder(c,id);if(r==null)return;Set<String> fired=new HashSet<>(prefs(c).getStringSet("fired_ids",Collections.emptySet()));if(fired.contains(id))return;try{if(at(r)>System.currentTimeMillis()+1000){reconcile(c);return;}}catch(Exception e){return;}if(!enabled(c))return;
 Intent open=new Intent(c,MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent tap=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
 String kind=r.optString("kind"),name=r.optString("name");String title="homework".equals(kind)?"作业提醒":"activity".equals(kind)?"活动提醒":"你的提醒";
 Notification notification=new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_notification).setContentTitle(title).setContentText(name).setStyle(new Notification.BigTextStyle().bigText(name)).setContentIntent(tap).setAutoCancel(true).setShowWhen(true).setWhen(System.currentTimeMillis()).build();
 try{c.getSystemService(NotificationManager.class).notify(id,0,notification);fired.add(id);prefs(c).edit().putStringSet("fired_ids",fired).commit();}catch(SecurityException e){/* Permission revoked between check and delivery. */}
 }
 static String statusJson(Context c){JSONObject result=new JSONObject(),states=new JSONObject();try{boolean enabled=enabled(c),exact=exact(c);result.put("enabled",enabled);result.put("exact",exact);Set<String> fired=prefs(c).getStringSet("fired_ids",Collections.emptySet());JSONArray rows=reminders(c);for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null)continue;try{states.put(r.optString("id"),AlarmPlan.status(at(r),System.currentTimeMillis(),fired.contains(r.optString("id")),enabled,exact));}catch(Exception e){states.put(r.optString("id"),"日期或时区需检查");}}result.put("states",states);}catch(Exception e){}return result.toString();}
}
